/**
 * Pharos demo AI endpoint, running on Cloudflare Workers AI (free daily allowance).
 *
 *   GET  /health   → is it up, which model, how many AI answers are left today
 *   POST /chat     → { input }  the Keeper answers from the help-center excerpts in `input`
 *   POST /triage   → { input }  returns the triage JSON for the ticket in `input`
 *   GET  /inbox    → real emails that arrived for the demo desk (needs the X-Inbox-Key header)
 *
 * Real email (optional): Cloudflare Email Routing sends an address on your own domain to this Worker's
 * email() handler. Only senders in EMAIL_ALLOWLIST are accepted; everyone else is rejected. Accepted
 * emails (the latest 20) are kept in LIMITS for 24 hours and handed to the agent desk through /inbox.
 *
 * Protections, so the free allowance can't be drained:
 *   - Only the origins in ALLOWED_ORIGINS get answers (your GitHub Pages site).
 *   - The system prompts live HERE, not in the page, so callers can't repurpose the model.
 *   - Input size is capped, output length is capped.
 *   - A per-visitor and a global daily cap, counted in a KV namespace bound as LIMITS.
 *     Visitor IPs are hashed before they're used as a key; raw IPs are never stored.
 *
 * Bindings (Settings > Bindings in the Cloudflare dashboard):
 *   AI      Workers AI
 *   LIMITS  a KV namespace
 * Variables (Settings > Variables and secrets):
 *   ALLOWED_ORIGINS     e.g. https://scenebiscuit-cell.github.io
 *   PER_VISITOR_DAILY   default 10
 *   GLOBAL_DAILY        default 40 (keeps you well under the free allowance)
 *   MODEL               optional; a different Workers AI text model id
 * Secrets, only for the real-email inbox (add them as type "Secret" so they stay out of the repo):
 *   EMAIL_ALLOWLIST     comma-separated sender addresses allowed to email the demo desk
 *   INBOX_KEY           a long random string; the agent desk must send it to read /inbox
 *   INBOX_ADDRESS       optional; the address shown in the desk, e.g. support@yourdomain.com
 *
 * This file is generated by build_demo.py from worker/worker.template.js. Edit the template, not this file.
 */
const DEFAULT_MODEL = "@cf/meta/llama-3.3-70b-instruct-fp8-fast";
const PROMPTS = {
  "chat": "You are the help-center assistant for Pharos, project management software for small teams.\n\nAnswer the customer's question using ONLY the HELP CENTER EXCERPTS below.\n- If the excerpts don't contain the answer, reply exactly: HANDOFF\n- Never guess at prices, policies, or features that aren't in the excerpts.\n- Be brief, warm, and human: 2 to 6 sentences, or short numbered steps. Use contractions.\n- Don't repeat the customer's question back to them. Answer it.\n- Use the exact menu paths from the docs, like Settings > Billing.\n- End with one line: \"Source: <article title>\".",
  "triage": "You are a support operations assistant for Pharos, project management software for small teams (agencies, studios, startups). You triage incoming support tickets and draft replies that a human agent reviews before sending.\n\nRules:\n- Use only facts found in the HELP CENTER EXCERPTS and MACROS. Never invent features, prices, dates, or policies.\n- Follow the refund policy exactly. Never promise a refund the policy does not allow.\n- Write the reply as the agent will send it after taking the actions the chosen macro describes.\n- Never ask the customer for their password.\n- Security reports: thank the reporter, say it has been escalated, point them to security@pharos.example, and do not confirm or discuss details.\n- Spam or vendor pitches: draft_reply must be an empty string.\n- Answer every question the customer asked. If something is not supported, say so plainly and offer the closest workaround from the docs.\n- Plain language, short paragraphs, numbered steps when there are steps. Under 180 words. Sign off as \"Alex\" then \"Pharos Support\" on the next line.\n\nVoice (this matters as much as accuracy):\n- Sound like a kind, experienced person who likes helping, not a script. Use contractions and everyday words.\n- Open with \"Thank you for contacting Pharos.\" Never write \"Thanks for reaching out.\"\n- Do NOT restate or summarize the customer's problem back to them. They know what they wrote. Go straight to a short, sincere acknowledgment (only when it fits) and then the answer.\n- Never use corporate filler: \"I understand your frustration\", \"We apologize for any inconvenience\", \"rest assured\", \"please be advised\", \"I hope this email finds you well\".\n- When Pharos made the mistake (an extra or wrong charge, a bug, an outage), say so plainly and apologize once, briefly, then say what you've done about it. One short apology is enough; don't grovel or repeat it.\n- Billing surprises: be kind and matter-of-fact. A light \"sorry about that\" or \"I can see how that was a surprise\" is plenty, then explain clearly. Never sound defensive about the policy.\n- Use the chosen macro for facts and steps, but write it in your own words for this customer. Don't copy it line for line.\n\nPriority guide:\n- urgent: Pharos down for many users, or a security issue\n- high: a team is blocked from working, a client deadline is at risk, can't access their account with work due, wrong or double charges, repeated failures, or a frustrated customer threatening to leave\n- normal: a how-to question or a single problem with a workaround\n- low: feature requests, praise, spam\n\nReturn one JSON object with exactly these keys:\ncategory: one of billing, refund, cancellation, integrations, notifications, workspace_setup, bug, account_access, seats, data_privacy, outage, security, feature_request, presales, feedback, spam\npriority: one of low, normal, high, urgent\nsentiment: one of negative, neutral, positive\nchurn_risk: true or false\nmacro_id: the id of the macro your reply is based on\ntags: a list of 2 to 5 short snake_case tags\nsummary: one sentence telling the agent what the customer needs\ndraft_reply: the reply text\nneeds_human: true if a person must do something before replying (refund, identity check, escalation, investigation)\ncited_articles: list of help-center slugs you relied on\nconfidence: a number from 0 to 1\n\nRespond with a single JSON object and nothing else."
};
const MAIL = { key: "mail:recent", maxBytes: 256 * 1024, maxBody: 4000, perDay: 40, ttl: 60 * 60 * 24, maxList: 20 };
const LIMITS = { chat: { maxInput: 8000, maxTokens: 400 }, triage: { maxInput: 14000, maxTokens: 900 } };

export default {
  async fetch(req, env, ctx) {
    const allowed = String(env.ALLOWED_ORIGINS || "").split(",").map(s => s.trim().replace(/\/$/, "")).filter(Boolean);
    const origin = req.headers.get("Origin") || "";
    const okOrigin = allowed.includes(origin);
    const cors = {
      "Access-Control-Allow-Origin": okOrigin ? origin : (allowed[0] || "null"),
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, X-Inbox-Key",
      "Access-Control-Max-Age": "86400",
      "Vary": "Origin",
    };
    const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { ...cors, "Content-Type": "application/json" } });

    if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    const path = new URL(req.url).pathname.replace(/\/$/, "") || "/";
    const perVisitor = Number(env.PER_VISITOR_DAILY) || 10;
    const global = Number(env.GLOBAL_DAILY) || 40;
    const day = new Date().toISOString().slice(0, 10);
    const MODEL = env.MODEL || DEFAULT_MODEL;

    if (path === "/health" || path === "/") {
      if (!env.AI || !env.LIMITS) return json({ ok: false, error: "not_configured", message: "Add the AI and LIMITS bindings in the Worker's settings." }, 503);
      const used = await count(env, `all:${day}`);
      return json({ ok: true, model: MODEL, remaining_today: Math.max(0, global - used), per_visitor_daily: perVisitor });
    }
    // Real emails for the agent desk. Off unless INBOX_KEY is set, and only for a desk that holds the key.
    if (req.method === "GET" && path === "/inbox") {
      if (!env.INBOX_KEY || !env.LIMITS) return json({ error: "not_found" }, 404);
      if (!okOrigin) return json({ error: "forbidden_origin", message: "This endpoint only serves the Pharos demo site." }, 403);
      if (!(await sameSecret(req.headers.get("X-Inbox-Key") || "", env.INBOX_KEY))) return json({ error: "bad_key", message: "That inbox key isn't valid." }, 401);
      const since = Number(new URL(req.url).searchParams.get("since")) || 0;
      const emails = (await readMail(env)).filter(e => Number(String(e.id).split(":")[0]) > since);
      return json({ ok: true, address: env.INBOX_ADDRESS || "", emails });
    }
    if (req.method !== "POST" || !(path === "/chat" || path === "/triage")) return json({ error: "not_found" }, 404);
    if (!okOrigin) return json({ error: "forbidden_origin", message: "This AI endpoint only serves the Pharos demo site." }, 403);
    if (!env.AI || !env.LIMITS) return json({ error: "not_configured", message: "The demo's AI isn't set up yet." }, 503);

    const kind = path.slice(1);
    let body;
    try { body = await req.json(); } catch { return json({ error: "bad_request", message: "Send JSON with an `input` field." }, 400); }
    const input = typeof body?.input === "string" ? body.input.trim() : "";
    if (!input) return json({ error: "bad_request", message: "Missing input." }, 400);
    if (input.length > LIMITS[kind].maxInput) return json({ error: "too_long", message: "That request is too long for the demo." }, 413);

    // Daily caps. KV is eventually consistent, so these are approximate, which is fine for a demo.
    const visitor = await sha256((req.headers.get("CF-Connecting-IP") || "unknown") + "|" + day);
    const vKey = `v:${day}:${visitor.slice(0, 24)}`, gKey = `all:${day}`;
    const [vUsed, gUsed] = await Promise.all([count(env, vKey), count(env, gKey)]);
    if (gUsed >= global) return json({ error: "daily_limit", message: "The demo has used today's free AI answers. It resets at midnight UTC." }, 429);
    if (vUsed >= perVisitor) return json({ error: "visitor_limit", message: `You've used your ${perVisitor} AI answers for today. The docs-only mode still works.` }, 429);
    ctx.waitUntil(Promise.all([bump(env, vKey, vUsed), bump(env, gKey, gUsed)]));

    try {
      const out = await env.AI.run(MODEL, {
        messages: [{ role: "system", content: PROMPTS[kind] }, { role: "user", content: input }],
        max_tokens: LIMITS[kind].maxTokens,
        temperature: 0.2,
      });
      const r = out?.response;
      const raw = typeof r === "string" ? r : r ? JSON.stringify(r) : "";
      const text = kind === "triage" ? polishTriage(raw, input) : scrub(raw);
      return json({ text, model: MODEL, remaining_today: Math.max(0, global - gUsed - 1) });
    } catch (e) {
      return json({ error: "model_error", message: "The AI model didn't answer. Try again in a moment." }, 502);
    }
  },

  // A real email arrived (Cloudflare Email Routing → this Worker). Allowlisted senders only.
  async email(message, env, ctx) {
    const allow = String(env.EMAIL_ALLOWLIST || "").toLowerCase().split(",").map(s => s.trim()).filter(Boolean);
    const sender = String(message.from || "").trim().toLowerCase();
    if (!env.LIMITS || !allow.length || !allow.includes(sender)) return message.setReject("This demo inbox only accepts mail from approved senders.");
    if (message.rawSize > MAIL.maxBytes) return message.setReject("That message is too large for the demo inbox.");
    // A sender address can be forged; mail that fails the sending domain's own checks is turned away.
    if (/\bdmarc=fail\b/i.test(message.headers.get("authentication-results") || "")) return message.setReject("This message failed sender verification.");
    const day = new Date().toISOString().slice(0, 10), cKey = `mailcount:${day}`;
    const used = await count(env, cKey);
    if (used >= (Number(env.INBOX_DAILY) || MAIL.perDay)) return message.setReject("The demo inbox is full for today.");

    const mail = parseEmail(await rawToBinary(message.raw));
    if (mail.email && !allow.includes(mail.email)) return message.setReject("This demo inbox only accepts mail from approved senders.");
    const at = Date.now(), id = `${at}:${crypto.randomUUID().slice(0, 8)}`;
    const record = { id, at: new Date(at).toISOString(), from: { name: mail.name || sender.split("@")[0], email: mail.email || sender },
      subject: (mail.subject || "(no subject)").slice(0, 200), body: tidyBody(mail.text).slice(0, MAIL.maxBody) };
    const kept = (await readMail(env)).filter(e => at - Number(String(e.id).split(":")[0]) < MAIL.ttl * 1000);
    await env.LIMITS.put(MAIL.key, JSON.stringify([...kept, record].slice(-MAIL.maxList)), { expirationTtl: MAIL.ttl });
    ctx.waitUntil(bump(env, cKey, used));
  },
};

// ---------- reading an email ----------
// A small MIME reader (no libraries, so the Worker stays a single file): headers, multipart bodies,
// base64 and quoted-printable, and encoded subjects. It prefers the plain-text part.
async function rawToBinary(stream) {
  const bytes = new Uint8Array(await new Response(stream).arrayBuffer());
  let out = "";
  for (let i = 0; i < bytes.length; i += 8192) out += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));
  return out;   // one character per byte, so encoded parts can be decoded exactly
}
const toBytes = bin => Uint8Array.from(bin, c => c.charCodeAt(0) & 255);
function decodeText(bin, charset) {
  try { return new TextDecoder(charset || "utf-8").decode(toBytes(bin)); }
  catch { return new TextDecoder("utf-8").decode(toBytes(bin)); }
}
const fromQP = s => s.replace(/=\r?\n/g, "").replace(/=([0-9A-Fa-f]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
function fromB64(s) { try { return atob(s.replace(/[^A-Za-z0-9+/=]/g, "")); } catch { return ""; } }
function splitMessage(bin) {
  const m = bin.match(/\r?\n\r?\n/);
  const head = m ? bin.slice(0, m.index) : bin, body = m ? bin.slice(m.index + m[0].length) : "";
  const headers = {};
  for (const line of head.replace(/\r?\n[ \t]+/g, " ").split(/\r?\n/)) {
    const i = line.indexOf(":");
    if (i > 0) { const k = line.slice(0, i).trim().toLowerCase(); if (!(k in headers)) headers[k] = line.slice(i + 1).trim(); }
  }
  return { headers, body };
}
const param = (value, name) => (String(value).match(new RegExp(name + '\\s*=\\s*"?([^";]+)"?', "i")) || [])[1] || "";
// Encoded header words, e.g. =?UTF-8?B?…?= or =?UTF-8?Q?…?=
function decodeWords(s) {
  return String(s).replace(/(=\?[^?]+\?[BbQq]\?[^?]*\?=)\s+(?==\?)/g, "$1")
    .replace(/=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g, (_, cs, enc, txt) =>
      decodeText(enc.toUpperCase() === "B" ? fromB64(txt) : fromQP(txt.replace(/_/g, " ")), cs));
}
function htmlToText(html) {
  return html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, "").replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|div|li|tr|h[1-6])>/gi, "\n")
    .replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}
function bodyText(headers, body, depth = 0) {
  const type = (headers["content-type"] || "text/plain").toLowerCase();
  if (type.startsWith("multipart/") && depth < 5) {
    const boundary = param(headers["content-type"], "boundary");
    if (!boundary) return { plain: "", html: "" };
    let plain = "", html = "";
    for (const chunk of body.split("--" + boundary).slice(1)) {
      if (chunk.startsWith("--")) break;                      // closing boundary
      const part = splitMessage(chunk.replace(/^\r?\n/, ""));
      if (/attachment/i.test(part.headers["content-disposition"] || "")) continue;
      const got = bodyText(part.headers, part.body, depth + 1);
      plain = plain || got.plain; html = html || got.html;
    }
    return { plain, html };
  }
  if (!type.startsWith("text/")) return { plain: "", html: "" };
  const enc = (headers["content-transfer-encoding"] || "").toLowerCase();
  const text = decodeText(enc === "base64" ? fromB64(body) : enc === "quoted-printable" ? fromQP(body) : body, param(headers["content-type"], "charset"));
  return type.startsWith("text/html") ? { plain: "", html: htmlToText(text) } : { plain: text, html: "" };
}
function parseEmail(bin) {
  const { headers, body } = splitMessage(bin);
  const from = decodeWords(headers.from || "");
  const addr = (from.match(/<([^<>\s]+@[^<>\s]+)>/) || from.match(/([^\s<>"]+@[^\s<>"]+)/) || [])[1] || "";
  const name = from.replace(/<[^>]*>/g, "").replace(/["']/g, "").trim();
  const got = bodyText(headers, body);
  return { subject: decodeWords(headers.subject || "").trim(), name: name === addr ? "" : name, email: addr.toLowerCase(), text: got.plain || got.html };
}
// Keep what the customer wrote: drop quoted replies, the "-- " signature block, and extra blank lines.
function tidyBody(text) {
  const out = [];
  for (const line of String(text).replace(/\r\n?/g, "\n").split("\n")) {
    if (/^On .{5,200} wrote:\s*$/.test(line) || /^-{2,}\s*(Forwarded|Original) message/i.test(line) || /^--\s?$/.test(line)) break;
    if (/^>/.test(line)) continue;
    out.push(line.replace(/\s+$/, ""));
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

// ---------- voice guard ----------
// Smaller open models don't always follow the house style, so the Worker enforces the
// non-negotiables after the model answers: no corporate filler, the standard opening,
// and the standard sign-off. The agent still reviews every draft before it's sent.
const BANNED = [
  /\bI (?:completely |totally |truly )?understand (?:your|how) (?:frustrat\w*|frustrating[^.!?]*)/i,
  /\bI understand (?:your|the) (?:concern|frustration)/i,
  /\bwe apologi[sz]e for any inconvenience/i,
  /\bsorry for any inconvenience/i,
  /\brest assured\b/i,
  /\bplease be advised\b/i,
  /\bI hope this (?:e-?mail|message) finds you well/i,
  /\bthank(?:s| you) for reaching out\b/i,
];
const OPENING = "Thank you for contacting Pharos.";
const AGENT = "Alex";

// Drop any sentence that contains a banned phrase.
function scrub(text) {
  return String(text)
    .split(/\n/)
    .map(line => line.split(/(?<=[.!?])\s+/).filter(s => !BANNED.some(re => re.test(s))).join(" "))
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function fixDraft(draft, firstName = "") {
  // Greeting: pull "Hi Name," off first so scrubbing a filler sentence can't take it with it.
  let greeting = "", body = String(draft).trim();
  const m = body.match(/^((?:hi|hello|hey|dear)\b[^,\n]{0,40},)\s*/i);
  if (m) { greeting = m[1]; body = body.slice(m[0].length); }
  let rest = scrub(body);
  if (!rest && !greeting) return rest;
  // The model sometimes skips the greeting; the ticket's From: line has the name.
  if (!greeting && firstName) greeting = `Hi ${firstName},`;
  // Opening line.
  if (!/^thank you for contacting pharos/i.test(rest)) rest = `${OPENING} ${rest}`.trim();
  // Sign-off: strip whatever the model used, then add the standard one.
  rest = rest.replace(/\n+(?:best|thanks|cheers|regards|kind regards|best regards|sincerely|warmly)[,!]?\s*\n+[\s\S]{0,80}$/i, "")
             .replace(/\n*\b(?:[A-Z][a-z]+\s*\n)?Pharos Support\s*$/i, "")
             .replace(/\s*\b(?:Alex)\s*$/,"")
             .trim()
             // a closing left on the last line, e.g. "...follow up. Best," or "Wishing you all the best,"
             .replace(/\s*\b(?:wishing you all the best|all the best|best regards|kind regards|warm regards|best|regards|thanks|thank you|cheers|sincerely|warmly|take care|all the best|wishing you all the best|with thanks)[^.!?\n]{0,25}[,!]?\s*$/i, "")
             .trim();
  return `${greeting ? greeting + "\n\n" : ""}${rest}\n\nBest,\n${AGENT}\nPharos Support`;
}

function polishTriage(raw, input = "") {
  const cleaned = String(raw).trim().replace(/^```(?:json)?\s*|\s*```$/g, "");
  let obj;
  try { obj = JSON.parse(cleaned); }
  catch {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (!m) return raw;
    try { obj = JSON.parse(m[0]); } catch { return raw; }
  }
  const from = String(input).match(/^From:\s*([A-Za-z][A-Za-z'-]*)/m);
  if (typeof obj.draft_reply === "string" && obj.category !== "spam") obj.draft_reply = fixDraft(obj.draft_reply, from ? from[1] : "");
  if (Array.isArray(obj.cited_articles)) obj.cited_articles = obj.cited_articles.map(s => String(s).split(">")[0].trim());
  return JSON.stringify(obj);
}

async function count(env, key) { const v = await env.LIMITS.get(key); return Number(v) || 0; }
async function bump(env, key, current) { await env.LIMITS.put(key, String(current + 1), { expirationTtl: 60 * 60 * 48 }); }
// Recent emails live under one key, so the desk's check is a single read. KV caches reads for at least
// 30 seconds, which is the longest a new email takes to show up.
async function readMail(env) {
  try { const v = JSON.parse((await env.LIMITS.get(MAIL.key, { cacheTtl: 30 })) || "[]"); return Array.isArray(v) ? v : []; }
  catch { return []; }
}
// Compare two secrets without leaking where they differ.
async function sameSecret(a, b) { return a.length > 0 && (await sha256("k|" + a)) === (await sha256("k|" + b)); }
async function sha256(s) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join("");
}
